Q: How to determine the current iPhone/device model? A: <p>I made this &quot;pure Swift&quot; extension on <a href="https://developer.apple.com/library/ios/documentation/UIKit/Reference/UIDevice_Class/index.html#//apple_ref/occ/cl/UIDevice" rel="nofollow noreferrer"><code>UIDevice</code></a>.</p>
<p>If you are looking for a more elegant solution you can use <a href="https://github.com/dennisweissmann/DeviceKit" rel="nofollow noreferrer">my µ-framework <code>DeviceKit</code></a> published on GitHub (also available via CocoaPods, Carthage and Swift Package Manager).</p>
<p>Here's the code:</p>
<pre><code>import UIKit

public extension UIDevice {

    static let modelName: String = {
        var systemInfo = utsname()
        uname(&amp;systemInfo)
        let machineMirror = Mirror(reflecting: systemInfo.machine)
        let identifier = machineMirror.children.reduce(&quot;&quot;) { identifier, element in
            guard let value = element.value as? Int8, value != 0 else { return identifier }
            return identifier + String(UnicodeScalar(UInt8(value)))
        }

        func mapToDevice(identifier: String) -&gt; String { // swiftlint:disable:this cyclomatic_complexity
            #if os(iOS)
            switch identifier {
            case &quot;iPod5,1&quot;:                                       return &quot;iPod touch (5th generation)&quot;
            case &quot;iPod7,1&quot;:                                       return &quot;iPod touch (6th generation)&quot;
            case &quot;iPod9,1&quot;:                                       return &quot;iPod touch (7th generation)&quot;
            case &quot;iPhone3,1&quot;, &quot;iPhone3,2&quot;, &quot;iPhone3,3&quot;:           return &quot;iPhone 4&quot;
            case &quot;iPhone4,1&quot;:                                     return &quot;iPhone 4s&quot;
            case &quot;iPhone5,1&quot;, &quot;iPhone5,2&quot;:                        return &quot;iPhone 5&quot;
            case &quot;iPhone5,3&quot;, &quot;iPhone5,4&quot;:                        return &quot;iPhone 5c&quot;
            case &quot;iPhone6,1&quot;, &quot;iPhone6,2&quot;:                        return &quot;iPhone 5s&quot;
            case &quot;iPhone7,2&quot;:                                     return &quot;iPhone 6&quot;
            case &quot;iPhone7,1&quot;:                                     return &quot;iPhone 6 Plus&quot;
            case &quot;iPhone8,1&quot;:                                     return &quot;iPhone 6s&quot;
            case &quot;iPhone8,2&quot;:                                     return &quot;iPhone 6s Plus&quot;
            case &quot;iPhone9,1&quot;, &quot;iPhone9,3&quot;:                        return &quot;iPhone 7&quot;
            case &quot;iPhone9,2&quot;, &quot;iPhone9,4&quot;:                        return &quot;iPhone 7 Plus&quot;
            case &quot;iPhone10,1&quot;, &quot;iPhone10,4&quot;:                      return &quot;iPhone 8&quot;
            case &quot;iPhone10,2&quot;, &quot;iPhone10,5&quot;:                      return &quot;iPhone 8 Plus&quot;
            case &quot;iPhone10,3&quot;, &quot;iPhone10,6&quot;:                      return &quot;iPhone X&quot;
            case &quot;iPhone11,2&quot;:                                    return &quot;iPhone XS&quot;
            case &quot;iPhone11,4&quot;, &quot;iPhone11,6&quot;:                      return &quot;iPhone XS Max&quot;
            case &quot;iPhone11,8&quot;:                                    return &quot;iPhone XR&quot;
            case &quot;iPhone12,1&quot;:                                    return &quot;iPhone 11&quot;
            case &quot;iPhone12,3&quot;:                                    return &quot;iPhone 11 Pro&quot;
            case &quot;iPhone12,5&quot;:                                    return &quot;iPhone 11 Pro Max&quot;
            case &quot;iPhone13,1&quot;:                                    return &quot;iPhone 12 mini&quot;
            case &quot;iPhone13,2&quot;:                                    return &quot;iPhone 12&quot;
            case &quot;iPhone13,3&quot;:                                    return &quot;iPhone 12 Pro&quot;
            case &quot;iPhone13,4&quot;:                                    return &quot;iPhone 12 Pro Max&quot;
            case &quot;iPhone14,4&quot;:                                    return &quot;iPhone 13 mini&quot;
            case &quot;iPhone14,5&quot;:                                    return &quot;iPhone 13&quot;
            case &quot;iPhone14,2&quot;:                                    return &quot;iPhone 13 Pro&quot;
            case &quot;iPhone14,3&quot;:                                    return &quot;iPhone 13 Pro Max&quot;
            case &quot;iPhone14,7&quot;:                                    return &quot;iPhone 14&quot;
            case &quot;iPhone14,8&quot;:                                    return &quot;iPhone 14 Plus&quot;
            case &quot;iPhone15,2&quot;:                                    return &quot;iPhone 14 Pro&quot;
            case &quot;iPhone15,3&quot;:                                    return &quot;iPhone 14 Pro Max&quot;
            case &quot;iPhone15,4&quot;:                                    return &quot;iPhone 15&quot;
            case &quot;iPhone15,5&quot;:                                    return &quot;iPhone 15 Plus&quot;
            case &quot;iPhone16,1&quot;:                                    return &quot;iPhone 15 Pro&quot;
            case &quot;iPhone16,2&quot;:                                    return &quot;iPhone 15 Pro Max&quot;
            case &quot;iPhone17,3&quot;:                                    return &quot;iPhone 16&quot;
            case &quot;iPhone17,4&quot;:                                    return &quot;iPhone 16 Plus&quot;
            case &quot;iPhone17,1&quot;:                                    return &quot;iPhone 16 Pro&quot;
            case &quot;iPhone17,2&quot;:                                    return &quot;iPhone 16 Pro Max&quot;
            case &quot;iPhone17,5&quot;:                                    return &quot;iPhone 16e&quot;
            case &quot;iPhone18,3&quot;:                                    return &quot;iPhone 17&quot;
            case &quot;iPhone18,4&quot;:                                    return &quot;iPhone Air&quot;
            case &quot;iPhone18,1&quot;:                                    return &quot;iPhone 17 Pro&quot;
            case &quot;iPhone18,2&quot;:                                    return &quot;iPhone 17 Pro Max&quot;
            case &quot;iPhone18,5&quot;:                                    return &quot;iPhone 17e&quot;
            case &quot;iPhone19,2&quot;:                                    return &quot;iPhone 18 Pro&quot;
            case &quot;iPhone19,3&quot;, &quot;iPhone19,7&quot;:                      return &quot;iPhone 18 Pro Max&quot;
            case &quot;iPhone19,4&quot;:                                    return &quot;iPhone Duo&quot;
            case &quot;iPhone8,4&quot;:                                     return &quot;iPhone SE&quot;
            case &quot;iPhone12,8&quot;:                                    return &quot;iPhone SE (2nd generation)&quot;
            case &quot;iPhone14,6&quot;:                                    return &quot;iPhone SE (3rd generation)&quot;
            case &quot;iPad2,1&quot;, &quot;iPad2,2&quot;, &quot;iPad2,3&quot;, &quot;iPad2,4&quot;:      return &quot;iPad 2&quot;
            case &quot;iPad3,1&quot;, &quot;iPad3,2&quot;, &quot;iPad3,3&quot;:                 return &quot;iPad (3rd generation)&quot;
            case &quot;iPad3,4&quot;, &quot;iPad3,5&quot;, &quot;iPad3,6&quot;:                 return &quot;iPad (4th generation)&quot;
            case &quot;iPad6,11&quot;, &quot;iPad6,12&quot;:                          return &quot;iPad (5th generation)&quot;
            case &quot;iPad7,5&quot;, &quot;iPad7,6&quot;:                            return &quot;iPad (6th generation)&quot;
            case &quot;iPad7,11&quot;, &quot;iPad7,12&quot;:                          return &quot;iPad (7th generation)&quot;
            case &quot;iPad11,6&quot;, &quot;iPad11,7&quot;:                          return &quot;iPad (8th generation)&quot;
            case &quot;iPad12,1&quot;, &quot;iPad12,2&quot;:                          return &quot;iPad (9th generation)&quot;
            case &quot;iPad13,18&quot;, &quot;iPad13,19&quot;:                        return &quot;iPad (10th generation)&quot;
            case &quot;iPad15,7&quot;, &quot;iPad15,8&quot;:                          return &quot;iPad (11th generation)&quot;
            case &quot;iPad4,1&quot;, &quot;iPad4,2&quot;, &quot;iPad4,3&quot;:                 return &quot;iPad Air&quot;
            case &quot;iPad5,3&quot;, &quot;iPad5,4&quot;:                            return &quot;iPad Air 2&quot;
            case &quot;iPad11,3&quot;, &quot;iPad11,4&quot;:                          return &quot;iPad Air (3rd generation)&quot;
            case &quot;iPad13,1&quot;, &quot;iPad13,2&quot;:                          return &quot;iPad Air (4th generation)&quot;
            case &quot;iPad13,16&quot;, &quot;iPad13,17&quot;:                        return &quot;iPad Air (5th generation)&quot;
            case &quot;iPad14,8&quot;, &quot;iPad14,9&quot;:                          return &quot;iPad Air (11-inch) (M2)&quot;
            case &quot;iPad14,10&quot;, &quot;iPad14,11&quot;:                        return &quot;iPad Air (13-inch) (M2)&quot;
            case &quot;iPad15,3&quot;, &quot;iPad15,4&quot;:                          return &quot;iPad Air (11-inch) (M3)&quot;
            case &quot;iPad15,5&quot;, &quot;iPad15,6&quot;:                          return &quot;iPad Air (13-inch) (M3)&quot;
            case &quot;iPad16,8&quot;, &quot;iPad16,9&quot;:                          return &quot;iPad Air (11-inch) (M4)&quot;
            case &quot;iPad16,10&quot;, &quot;iPad16,11&quot;:                        return &quot;iPad Air (13-inch) (M4)&quot;
            case &quot;iPad2,5&quot;, &quot;iPad2,6&quot;, &quot;iPad2,7&quot;:                 return &quot;iPad mini&quot;
            case &quot;iPad4,4&quot;, &quot;iPad4,5&quot;, &quot;iPad4,6&quot;:                 return &quot;iPad mini 2&quot;
            case &quot;iPad4,7&quot;, &quot;iPad4,8&quot;, &quot;iPad4,9&quot;:                 return &quot;iPad mini 3&quot;
            case &quot;iPad5,1&quot;, &quot;iPad5,2&quot;:                            return &quot;iPad mini 4&quot;
            case &quot;iPad11,1&quot;, &quot;iPad11,2&quot;:                          return &quot;iPad mini (5th generation)&quot;
            case &quot;iPad14,1&quot;, &quot;iPad14,2&quot;:                          return &quot;iPad mini (6th generation)&quot;
            case &quot;iPad16,1&quot;, &quot;iPad16,2&quot;:                          return &quot;iPad mini (A17 Pro)&quot;
            case &quot;iPad6,3&quot;, &quot;iPad6,4&quot;:                            return &quot;iPad Pro (9.7-inch)&quot;
            case &quot;iPad7,3&quot;, &quot;iPad7,4&quot;:                            return &quot;iPad Pro (10.5-inch)&quot;
            case &quot;iPad8,1&quot;, &quot;iPad8,2&quot;, &quot;iPad8,3&quot;, &quot;iPad8,4&quot;:      return &quot;iPad Pro (11-inch) (1st generation)&quot;
            case &quot;iPad8,9&quot;, &quot;iPad8,10&quot;:                           return &quot;iPad Pro (11-inch) (2nd generation)&quot;
            case &quot;iPad13,4&quot;, &quot;iPad13,5&quot;, &quot;iPad13,6&quot;, &quot;iPad13,7&quot;:  return &quot;iPad Pro (11-inch) (3rd generation)&quot;
            case &quot;iPad14,3&quot;, &quot;iPad14,4&quot;:                          return &quot;iPad Pro (11-inch) (4th generation)&quot;
            case &quot;iPad16,3&quot;, &quot;iPad16,4&quot;:                          return &quot;iPad Pro (11-inch) (M4)&quot;
            case &quot;iPad17,1&quot;, &quot;iPad17,2&quot;:                          return &quot;iPad Pro (11-inch) (M5)&quot;
            case &quot;iPad6,7&quot;, &quot;iPad6,8&quot;:                            return &quot;iPad Pro (12.9-inch) (1st generation)&quot;
            case &quot;iPad7,1&quot;, &quot;iPad7,2&quot;:                            return &quot;iPad Pro (12.9-inch) (2nd generation)&quot;
            case &quot;iPad8,5&quot;, &quot;iPad8,6&quot;, &quot;iPad8,7&quot;, &quot;iPad8,8&quot;:      return &quot;iPad Pro (12.9-inch) (3rd generation)&quot;
            case &quot;iPad8,11&quot;, &quot;iPad8,12&quot;:                          return &quot;iPad Pro (12.9-inch) (4th generation)&quot;
            case &quot;iPad13,8&quot;, &quot;iPad13,9&quot;, &quot;iPad13,10&quot;, &quot;iPad13,11&quot;:return &quot;iPad Pro (12.9-inch) (5th generation)&quot;
            case &quot;iPad14,5&quot;, &quot;iPad14,6&quot;:                          return &quot;iPad Pro (12.9-inch) (6th generation)&quot;
            case &quot;iPad16,5&quot;, &quot;iPad16,6&quot;:                          return &quot;iPad Pro (13-inch) (M4)&quot;
            case &quot;iPad17,3&quot;, &quot;iPad17,4&quot;:                          return &quot;iPad Pro (13-inch) (M5)&quot;
            case &quot;AppleTV5,3&quot;:                                    return &quot;Apple TV&quot;
            case &quot;AppleTV6,2&quot;:                                    return &quot;Apple TV 4K&quot;
            case &quot;AudioAccessory1,1&quot;:                             return &quot;HomePod&quot;
            case &quot;AudioAccessory5,1&quot;:                             return &quot;HomePod mini&quot;
            case &quot;i386&quot;, &quot;x86_64&quot;, &quot;arm64&quot;:                       return &quot;Simulator \(mapToDevice(identifier: ProcessInfo().environment[&quot;SIMULATOR_MODEL_IDENTIFIER&quot;] ?? &quot;iOS&quot;))&quot;
            default:                                              return identifier
            }
            #elseif os(tvOS)
            switch identifier {
            case &quot;AppleTV5,3&quot;: return &quot;Apple TV 4&quot;
            case &quot;AppleTV6,2&quot;, &quot;AppleTV11,1&quot;, &quot;AppleTV14,1&quot;: return &quot;Apple TV 4K&quot;
            case &quot;i386&quot;, &quot;x86_64&quot;: return &quot;Simulator \(mapToDevice(identifier: ProcessInfo().environment[&quot;SIMULATOR_MODEL_IDENTIFIER&quot;] ?? &quot;tvOS&quot;))&quot;
            default: return identifier
            }
            #elseif os(visionOS)
            switch identifier {
            case &quot;RealityDevice14,1&quot;: return &quot;Apple Vision Pro&quot;
            default: return identifier
            }
            #endif
        }

        return mapToDevice(identifier: identifier)
    }()

}
</code></pre>
<p>You call it like this:</p>
<pre><code>let modelName = UIDevice.modelName
</code></pre>
<p>For real devices it returns e.g. &quot;iPad Pro (12.9-inch) (5th generation)&quot;, for simulators it returns e.g. &quot;Simulator iPad Pro (12.9-inch) (5th generation)&quot;</p>
