Q: Reverse a string in php without using any string function A: <p>With a minor modifications</p>
<pre><code>&lt;?php

  $string = &quot;Hello&quot;;
  $reverse = &quot;&quot;;
  $i = 0;
  while($i &lt; strlen($string)){
    $reverse = $string[$i].$reverse;
    $i++;
  }
  echo $reverse;

?&gt;
</code></pre>

Q: How can I specify the editorconfig-derived OptionSet for an AdhocWorkspace in Roslyn? A: <p>I am using the code below for <code>Formatter.OrganizeImportsAsync</code>.
<code>public static async Task&lt;Document&gt; OrganizeImportsAsync(Document document, CancellationToken cancellationToken = default)</code></p>
<p>I expect that it will work with <code>Formatter.FormatAsync</code> given the doc comments</p>
<pre><code>    /// &lt;summary&gt;
    /// Formats the whitespace in a document.
    /// &lt;/summary&gt;
    /// &lt;param name=&quot;document&quot;&gt;The document to format.&lt;/param&gt;
    /// &lt;param name=&quot;options&quot;&gt;An optional set of formatting options. If these options are not supplied the current set of options from the document's workspace will be used.&lt;/param&gt;
    /// &lt;param name=&quot;cancellationToken&quot;&gt;An optional cancellation token.&lt;/param&gt;
    /// &lt;returns&gt;The formatted document.&lt;/returns&gt;
    public static Task&lt;Document&gt; FormatAsync(Document document, OptionSet? options = null, CancellationToken cancellationToken = default)
</code></pre>
<pre><code>using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Text;

    public static class AdhocEditorConfigWorkspaceHelper
    {
        private static readonly string tempDirectory = Path.GetTempPath();
        private static readonly string editorConfigPath = Path.Combine(tempDirectory, &quot;.editorconfig&quot;);

        public async static Task&lt;IEnumerable&lt;Document&gt;&gt; GetDocumentsAsync(
            string editorConfig,
            params CompilationUnitSyntax[] compilationUnits
        )
        {
            var workspace = new AdhocWorkspace();

            var project = workspace.AddProject(&quot;TempProject&quot;, LanguageNames.CSharp);
            project = project.AddAnalyzerConfigDocument(
                &quot;.editorconfig&quot;,
                SourceText.From(editorConfig), null, editorConfigPath).Project;

            int i = 0;
            foreach (var compilationUnit in compilationUnits)
            {
                project = project.AddDocument(&quot;TempDocument.cs&quot;, compilationUnit, filePath: GetDocumentPath(i++)).Project;
            }

            return project.Documents;
        }

        private static string GetDocumentPath(int index) =&gt; Path.Combine(tempDirectory, $&quot;TempDocument{index}.cs&quot;);
    }
</code></pre>
